    // ── undergroundworlds ────────────────────────────────────────────────────

    private void addUndergroundworlds(BiomeMapper mapper) {
        undergroundworldsUndergroundDesert(mapper);
        undergroundworldsUndergroundJungle(mapper);
        undergroundworldsUndergroundTundra(mapper);
    }

    private void undergroundworldsUndergroundDesert(BiomeMapper mapper) {
        var key = biomeKey("undergroundworlds", "underground_desert");
        addBiome(mapper, Climate.parameters(
            Climate.Parameter.span(0.6f, 1.0f),
            Climate.Parameter.span(-1.0f, -0.4f),
            Climate.Parameter.span(0.5f, 1.0f),
            Climate.Parameter.span(-1.0f, 1.0f),
            Climate.Parameter.span(0.2f, 0.9f),
            Climate.Parameter.span(0.0f, 1.0f),
            0.0f
        ), key);
    }

    private void undergroundworldsUndergroundJungle(BiomeMapper mapper) {
        var key = biomeKey("undergroundworlds", "underground_jungle");
        addBiome(mapper, Climate.parameters(
            Climate.Parameter.span(0.4f, 1.0f),
            Climate.Parameter.span(0.4f, 1.0f),
            Climate.Parameter.span(0.5f, 1.0f),
            Climate.Parameter.span(-1.0f, 1.0f),
            Climate.Parameter.span(0.2f, 0.9f),
            Climate.Parameter.span(0.0f, 1.0f),
            0.0f
        ), key);
    }

    private void undergroundworldsUndergroundTundra(BiomeMapper mapper) {
        var key = biomeKey("undergroundworlds", "underground_tundra");
        addBiome(mapper, Climate.parameters(
            Climate.Parameter.span(-1.0f, -0.5f),
            Climate.Parameter.span(0.0f, 1.0f),
            Climate.Parameter.span(0.5f, 1.0f),
            Climate.Parameter.span(0.0f, 1.0f),
            Climate.Parameter.span(0.2f, 0.9f),
            Climate.Parameter.span(0.0f, 1.0f),
            0.0f
        ), key);
    }


    private static ResourceKey<Biome> biomeKey(String namespace, String path) {
        return ResourceKey.create(Registries.BIOME,
            ResourceLocation.fromNamespaceAndPath(namespace, path));
    }
